#include <bits/stdc++.h>
using namespace std;

#define vi  vector<int>
#define vvi vector<vector<int> >
#define rep(i, n) for(int i = 0; i < n; ++i)

int main() {
	int h,w;
	set<vvi>t[11],u[11];
	set<vvi>::iterator itr_t[11],itr_u[11];

	cin>>h>>w;
	vvi T(h,vi(w)),U(h,vi(w)),v(h,vi(w));
	vi tmp(w);
	int x,y,z;

	rep(i,h)rep(j,w)cin>>T[i][j];
	rep(i,h)rep(j,w)U[i][j]=(i*w)+j+1;
	if(T==U){
		cout<<0<<endl;
		return 0;
	}

	t[0].insert(T);
	rep(i,10){
		itr_t[i]=t[i].begin();
		while(itr_t[i]!=t[i].end()){
			v=*(itr_t[i]);
			rep(xx,2)rep(yy,2){
				rep(i,h/2)rep(j,w-1){
					swap(v[i+xx][j+yy],v[h-2-i+xx][w-2-j+yy]);
					if(i*(w-1)+j+1>=((h-1)*(w-1))/2)break;
				}

				if(v==U){
					cout<<(i+1)<<endl;
					return 0;
				}
				if((t[i].count(v)==0)&&((i==0)||(t[i-1].count(v)==0)))t[i+1].insert(v);

				rep(i,h/2)rep(j,w-1){
					swap(v[i+xx][j+yy],v[h-2-i+xx][w-2-j+yy]);
					if(i*(w-1)+j+1>=((h-1)*(w-1))/2)break;
				}
			}
			itr_t[i]++;
		}
	}

	u[0].insert(U);
	rep(i,10){
		itr_u[i]=u[i].begin();
		while(itr_u[i]!=u[i].end()){
			v=*(itr_u[i]);
			rep(xx,2)rep(yy,2){
				rep(i,h/2)rep(j,w-1){
					swap(v[i+xx][j+yy],v[h-2-i+xx][w-2-j+yy]);
					if(i*(w-1)+j+1>=((h-1)*(w-1))/2)break;
				}

				if(t[10].count(v)==1){
					cout<<(i+11)<<endl;
					return 0;
				}
				if((u[i].count(v)==0)&&((i==0)||(u[i-1].count(v)==0)))u[i+1].insert(v);

				rep(i,h/2)rep(j,w-1){
					swap(v[i+xx][j+yy],v[h-2-i+xx][w-2-j+yy]);
					if(i*(w-1)+j+1>=((h-1)*(w-1))/2)break;
				}
			}
			itr_u[i]++;
		}
	}

	cout<<-1<<endl;
	return 0;
}
